"""Pinned Native lane readback requests for the 3(a) authored map."""
import hashlib

from geometry import open_drive

REQUESTS={
    'first_center_approach':(-40,0,1,-1,'Bidirectional'),
    'center_through_first_opportunity':(-9.5,0,14,-1,'Bidirectional'),
    'center_after_first_opportunity':(10,0,2,-1,'Bidirectional'),
    'later_through_lane':(35,3.5,2,-2,'Driving'),
    'first_left_exit':(-3,-20,4,-1,'Driving'),
    'later_left_exit':(47,-20,24,-1,'Driving')}


def survey(carla,mapping,native_hash=None):
    observed={}
    for name,(x,y,road,lane,lane_type) in REQUESTS.items():
        requested=getattr(carla.LaneType,lane_type)
        waypoint=mapping.get_waypoint(carla.Location(x=x,y=y,z=.2),
                                      project_to_road=False,lane_type=requested)
        if waypoint is None or waypoint.road_id!=road or waypoint.lane_id!=lane:
            raise RuntimeError('Native lane readback failed: '+name)
        if waypoint.lane_type!=requested or abs(waypoint.lane_width-3.5)>.15:
            raise RuntimeError('Native lane type/width differs: '+name)
        expected=[1,0] if 'exit' not in name else [0,-1]
        forward=waypoint.transform.get_forward_vector()
        if forward.x*expected[0]+forward.y*expected[1]<.98:
            raise RuntimeError('Native direction differs: '+name)
        observed[name]={'road_id':road,'lane_id':lane,'lane_type':lane_type,
                        'lane_width_m':waypoint.lane_width,'native_center_xy_m':[x,y]}
    return {'authored_map_sha256':hashlib.sha256(open_drive().encode()).hexdigest(),
            'native_map_sha256':native_hash,'source_kind':'original_native' if native_hash else 'synthetic_cpu',
            'readback':observed,'native_lane_types_verified':True,
            'physical_turn_only_design_verified':False,
            'driver_purpose_verified':False}

"""Source-bound saved 3(a) movement measurement; no automatic legal verdict."""
import hashlib
import json
import math
from pathlib import Path

LAW_TEXT_SHA256='e60d085d40eefb382cbfc682f8ae76b9930ff54e553d04416af7bb40bc547ab5'
CENTER_ROADS={1,14,2}


def _sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()


def _finite_pair(value,name):
    if not isinstance(value,list) or len(value)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in value):
        raise ValueError('Invalid '+name)
    return [float(v) for v in value]


def measure(folder):
    folder=Path(folder)
    source=folder/'native_samples.jsonl';survey_file=folder/'road_geometry.json'
    map_file=folder/'scene.xodr'
    purpose_file=folder/'declared_purpose.json'
    rows=[json.loads(s) for s in source.read_text().splitlines() if s.strip()]
    survey=json.loads(survey_file.read_text());purpose=json.loads(purpose_file.read_text())
    if not rows or len(rows)<20:raise ValueError('Saved Native interval too short')
    if survey.get('native_lane_types_verified') is not True or \
            survey.get('authored_map_sha256')!=_sha(map_file):
        raise ValueError('Native lane survey missing')
    if purpose.get('law_text_sha256')!=LAW_TEXT_SHA256 or purpose.get('case') not in ('controlled_1','controlled_2'):
        raise ValueError('Source-bound declared purpose missing')
    expected_purpose={'controlled_1':'left_turn_from_center_at_first_opportunity',
                      'controlled_2':'through_travel_then_later_left_from_through_lane'}
    if purpose.get('declaration')!=expected_purpose[purpose['case']]:
        raise ValueError('Declared purpose differs from controlled case')
    kinds={r.get('source_kind') for r in rows}
    if len(kinds)!=1 or kinds.pop() not in ('synthetic_cpu','original_native'):
        raise ValueError('Mixed or missing source provenance')
    kind=rows[0]['source_kind']
    if purpose.get('source_kind')!=kind or survey.get('source_kind')!=kind:
        raise ValueError('Source provenance mismatch')
    frames=[r.get('native_frame') for r in rows]
    if any(type(f) is not int for f in frames) or frames!=sorted(set(frames)):
        raise ValueError('Native frames unordered or duplicated')
    times=[r.get('time_s') for r in rows]
    if any(type(t) not in (int,float) or not math.isfinite(t) for t in times) or \
            any(b<=a for a,b in zip(times,times[1:])):
        raise ValueError('Native time order invalid')
    center=[];first_turn=[];first_exit=[];through=[];later_turn=[];later_exit=[]
    for row in rows:
        road=row.get('native_road_id');lane=row.get('native_lane_id')
        if type(road) is not int or type(lane) is not int:raise ValueError('Native lane identity missing')
        xy=_finite_pair(row.get('native_center_xy_m'),'Native center')
        body=row.get('native_body_xy_m')
        if not isinstance(body,list) or len(body)!=4:raise ValueError('Body footprint missing')
        body=[_finite_pair(p,'body vertex') for p in body]
        if road in CENTER_ROADS and lane==-1 and all(-1.75<=p[1]<=1.75 for p in body):
            center.append(row)
        if road==13 and lane==-1:first_turn.append(row)
        if road==4 and lane==-1:first_exit.append(row)
        if road==2 and lane==-2 and all(1.75<=p[1]<=5.25 for p in body):
            through.append(row)
        if road==23 and lane==-1:later_turn.append(row)
        if road==24 and lane==-1:later_exit.append(row)
    if not center:raise ValueError('No fully occupied center-lane body frames')
    if min(r['native_frame'] for r in center)>=min(frames)+len(frames)//2:
        raise ValueError('Center-lane use occurs too late for comparison')
    first_opportunity_through=[r for r in center if r['native_road_id'] in (14,2)
                               and r['native_center_xy_m'][0]>=-10]
    measured={
        'center_full_body_frames':len(center),
        'center_entry_frame':center[0]['native_frame'],
        'center_exit_frame':center[-1]['native_frame'],
        'center_approach_x_span_m':round(max(r['native_center_xy_m'][0] for r in center)-
                                         min(r['native_center_xy_m'][0] for r in center),4),
        'first_opportunity_center_through_frames':len(first_opportunity_through),
        'first_left_connector_frames':len(first_turn),
        'first_left_exit_frames':len(first_exit),
        'later_through_full_body_frames':len(through),
        'later_left_connector_frames':len(later_turn),
        'later_left_exit_frames':len(later_exit),
    }
    if purpose['case']=='controlled_1':
        movement=bool(first_turn and first_exit and not later_turn and not later_exit)
    else:
        movement=bool(first_opportunity_through and through and later_turn and later_exit and not first_turn)
    return {'format':'c394300-3a-saved-movement-v1','case':purpose['case'],
            'source_kind':kind,'source_hashes':{'native_samples.jsonl':_sha(source),
                'road_geometry.json':_sha(survey_file),'declared_purpose.json':_sha(purpose_file),
                'scene.xodr':_sha(map_file)},
            'map_sha256':survey['authored_map_sha256'],
            'declared_purpose':purpose.get('declaration'),
            'declared_purpose_is_observed_driver_intent':False,
            'measured':measured,'requested_movement_observed_in_saved_rows':movement,
            'actual_native_or_pixels_verified':False,
            'legal_verdict':None}


if __name__=='__main__':
    import argparse
    parser=argparse.ArgumentParser();parser.add_argument('folder');args=parser.parse_args()
    print(json.dumps(measure(args.folder),indent=2,sort_keys=True))

"""Source-hashed 3(a) fallback triggers; synthetic inputs remain synthetic."""
import hashlib
import json
import math
from pathlib import Path

TRIGGERS={
    'fallback1':{'metric':'center_lane_approach_span_m','threshold_m':10.0,
                 'reason':'Need enough measured center-lane approach to classify use before the first turn opportunity.'},
    'fallback2':{'metric':'max_pre_turn_route_error_m','threshold_m':.75,
                 'reason':'Body tracking near the first turn opportunity must preserve which movement occurred.'},
    'fallback3':{'metric':'center_lane_and_body_visible_fraction','threshold':.90,
                 'reason':'The center lane and subject body must be visible at the decisive frames.'}}


def _sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()


def evaluate(folder,candidate):
    if candidate not in TRIGGERS:raise ValueError('Unknown fallback')
    folder=Path(folder)
    source=folder/'native_samples.jsonl'
    rows=[json.loads(s) for s in source.read_text().splitlines() if s.strip()]
    frames=[r.get('native_frame') for r in rows]
    if not rows or any(type(f) is not int for f in frames) or frames!=sorted(set(frames)):
        raise ValueError('Missing or unordered Native samples')
    if any(r.get('source_kind') not in ('synthetic_cpu','original_native') for r in rows):
        raise ValueError('Native sample provenance missing')
    if len({r['source_kind'] for r in rows})!=1:
        raise ValueError('Mixed synthetic and original Native rows')
    sources={'native_samples.jsonl':_sha(source)}
    if candidate=='fallback1':
        values=[]
        for r in rows:
            if r.get('native_road_id')==1 and r.get('native_lane_id')==-1:
                xy=r.get('native_center_xy_m')
                if not isinstance(xy,list) or len(xy)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in xy):
                    raise ValueError('Invalid center-lane pose')
                if xy[0]<-10:values.append(float(xy[0]))
        span=max(values)-min(values) if len(values)>1 else 0.0
        metric={'center_lane_approach_span_m':round(span,4)}
        triggered=span<TRIGGERS[candidate]['threshold_m']
    elif candidate=='fallback2':
        values=[]
        for r in rows:
            xy=r.get('native_center_xy_m')
            if not isinstance(xy,list) or len(xy)!=2:raise ValueError('Native center pose missing')
            if -20<=xy[0]<=-8:
                request=r.get('controller_request')
                value=request.get('route_error_m') if isinstance(request,dict) else None
                if type(value) not in (int,float) or not math.isfinite(value) or value<0:
                    raise ValueError('Invalid observed route error')
                values.append(float(value))
        if not values:raise ValueError('No pre-turn tracking observations')
        metric={'max_pre_turn_route_error_m':round(max(values),4)}
        triggered=max(values)>TRIGGERS[candidate]['threshold_m']
    else:
        audit_path=folder/'pixel_visibility_audit.json'
        audit=json.loads(audit_path.read_text())
        if rows[0]['source_kind']=='original_native':
            if audit.get('independent_original_pixel_review') is not True:
                raise ValueError('Independent original pixel review missing')
        elif audit.get('review_scope')!='synthetic_cpu':
            raise ValueError('Synthetic pixel review scope missing')
        if audit.get('source_video_sha256')!=_sha(folder/'overview.mkv'):
            raise ValueError('Pixel audit source hash mismatch')
        flags=audit.get('frames')
        if not isinstance(flags,list) or [r.get('native_frame') for r in flags]!=frames:
            raise ValueError('Pixel audit frame coverage mismatch')
        if any(type(r.get('center_lane_visible')) is not bool or type(r.get('body_visible')) is not bool for r in flags):
            raise ValueError('Invalid original pixel annotation')
        fraction=sum(r['center_lane_visible'] and r['body_visible'] for r in flags)/len(flags)
        metric={'center_lane_and_body_visible_fraction':round(fraction,4)}
        triggered=fraction<TRIGGERS[candidate]['threshold']
        sources.update({'pixel_visibility_audit.json':_sha(audit_path),'overview.mkv':_sha(folder/'overview.mkv')})
    return {'candidate':candidate,'triggered':triggered,'metric':metric,
            'source_hashes':sources,'source_kind':rows[0]['source_kind'],
            'physical_success_claimed':False,'reason':TRIGGERS[candidate]['reason']}
